SELECT s.id, s.shift_name AS shiftName, s.shift_type AS shiftType, s.start_time AS startTime, s.end_time AS endTime, s.duration_hours AS durationHours, s.is_active AS isActive, s.sort_order AS sortOrder, s.description, s.color, s.create_time AS createTime, s.update_time AS updateTime, IFNULL(usage.assignment_count, 0) AS assignmentCount FROM jsh_schedule_shift s LEFT JOIN ( SELECT shift_id, COUNT(*) AS assignment_count FROM jsh_schedule_assignment WHERE tenant_id = #{tenantId,jdbcType=BIGINT} AND ifnull(delete_flag,'0') != '1' GROUP BY shift_id ) usage ON s.id = usage.shift_id WHERE s.tenant_id = #{tenantId,jdbcType=BIGINT} AND ifnull(s.delete_flag,'0') != '1'
AND s.shift_name LIKE #{bindShiftName}
AND s.shift_type = #{shiftType,jdbcType=VARCHAR}
AND s.is_active = #{isActive,jdbcType=TINYINT}
ORDER BY s.sort_order ASC, s.id DESC

SELECT s.id, s.shift_name AS shiftName, s.shift_type AS shiftType, s.color, COUNT(a.id) AS totalAssignments, COUNT(DISTINCT a.user_id) AS uniqueUsers, COUNT(CASE WHEN a.status = 'COMPLETED' THEN 1 END) AS completedAssignments, ROUND(AVG(a.work_hours), 2) AS avgWorkHours FROM jsh_schedule_shift s LEFT JOIN jsh_schedule_assignment a ON s.id = a.shift_id AND a.tenant_id = #{tenantId,jdbcType=BIGINT} AND ifnull(a.delete_flag,'0') != '1'
AND a.schedule_date >= #{startDate,jdbcType=DATE}
AND a.schedule_date <= #{endDate,jdbcType=DATE}
WHERE s.tenant_id = #{tenantId,jdbcType=BIGINT} AND ifnull(s.delete_flag,'0') != '1' GROUP BY s.id, s.shift_name, s.shift_type, s.color ORDER BY totalAssignments DESC, s.sort_order ASC

SELECT COUNT(*)
FROM jsh_schedule_assignment
WHERE shift_id = #{shiftId,jdbcType=BIGINT}
AND tenant_id = #{tenantId,jdbcType=BIGINT}
AND ifnull(delete_flag,'0') != '1'

SELECT id, shift_name, shift_type, start_time, end_time, duration_hours, is_active, sort_order, description, color, tenant_id, delete_flag, create_time, update_time, create_by, update_by FROM jsh_schedule_shift WHERE tenant_id = #{tenantId,jdbcType=BIGINT} AND ifnull(delete_flag,'0') != '1' AND is_active = 1
AND id != #{excludeId,jdbcType=BIGINT}
AND ( (start_time <= #{startTime,jdbcType=TIME} AND end_time > #{startTime,jdbcType=TIME}) OR (start_time < #{endTime,jdbcType=TIME} AND end_time >= #{endTime,jdbcType=TIME}) OR (start_time >= #{startTime,jdbcType=TIME} AND end_time <= #{endTime,jdbcType=TIME}) )

SELECT s.shift_name AS '班次名称', s.shift_type AS '班次类型', s.start_time AS '开始时间', s.end_time AS '结束时间', s.duration_hours AS '时长(小时)', CASE s.is_active WHEN 1 THEN '启用' ELSE '禁用' END AS '状态', s.description AS '描述', COUNT(a.id) AS '使用次数', s.create_time AS '创建时间' FROM jsh_schedule_shift s LEFT JOIN jsh_schedule_assignment a ON s.id = a.shift_id AND a.tenant_id = #{tenantId,jdbcType=BIGINT} AND ifnull(a.delete_flag,'0') != '1' WHERE s.tenant_id = #{tenantId,jdbcType=BIGINT} AND ifnull(s.delete_flag,'0') != '1'
AND s.shift_name LIKE #{bindShiftName}
AND s.shift_type = #{shiftType,jdbcType=VARCHAR}
AND s.is_active = #{isActive,jdbcType=TINYINT}
GROUP BY s.id, s.shift_name, s.shift_type, s.start_time, s.end_time, s.duration_hours, s.is_active, s.description, s.create_time ORDER BY s.sort_order ASC, s.id DESC

